INSERT INTO "route" ("source", "external_id", "url", "title_raw", "title", "description_raw", "description", "author", "distance_meters", "elevation_gain_meters", "elevation_loss_meters", "max_elevation_meters", "min_elevation_meters", "technical_difficulty", "trail_type", "moving_time_seconds", "total_time_seconds", "coordinates_count", "uploaded_at", "recorded_at", "coordinates") VALUES
('wikiloc', '9845229', 'https://www.wikiloc.com/hiking-trails/basses-de-monars-sant-sebastia-o-feliu-de-monars-sant-marc-1327-m-puig-de-les-bruixes-1393-m-comane-9845229', 'Basses de Monars-Sant Sebastià (or Feliu) de Monars-Sant Marc (1327 m.)-Puig de les Bruixes (1393 m.)-Comanegra (1557 m.)', '{"en":"Monars pools and Sant Sebastià loop","ca":"Circular Basses de Monars i Sant Sebastià","es":"Circular Basses de Monars y Sant Sebastià"}'::jsonb, 'Basses de Monars-Sant Sebastià (o Feliu) de Monars-Sant Marc (1327 m.)-Puig de les Bruixes (1393 m.)-Comanegra (1557 m.) Hiking trail in Beget, Catalogne (Espagne). Download its GPS track and follow the itinerary on a map. Aquesta ruta circular parteix de les Basses de Monars (1.300 m.) són als peus del Comanegra, es troba en un lloc molt bonic, on hi ha uns magnífics prats amb molt bones vistes. 
Per arribar a la Basses de Monars cal arribar fins Rocabruna i anar en direcció a Beget. A uns 2 km. de Rocabruna veurem una pista a la nostra esquerra on es troba un gran dipòsit de ciment. Hem de seguir aquesta pista de suau ascensió durant uns 7,7 quilòmetres fins arribar al cim de la Bassa on deixem el cotxe, al costat d’un rètol de l’Ajuntament de Montagut i Oix que posa “Benvinguts”. 
Nosaltres hem fet la pista amb un “tot camí”, però sense pressa es pot fer amb qualsevol tipus de cotxe. 
Començarem la ruta baixant i vorejant la Bassa, on trobem un indicador de camins que ens marca la direcció a Monars i Sant Sebastià. Seguirem baixant per un caminet molt fresat, passant per les ruïnes del corral i pel Mas Mitjà, per arribar a la casa de Cal Bessó amb l''església romànica i antiga parròquia de Sant Sebastià (o Sant Feliu) de Monars al seu davant. L’ermita que està datada des del 1064 és un exemplar interessant amb un absis trapezial i un campanar d''espadanya rústec, en aquests moments està abandonada, però el dintre està força net. 
Seguim endavant, i arribem al Torrent de la Font de Monars on hi ha un abeurador pel bestiar, que cal travessar per unes passeres de pedres. Seguim el camí que comença a enfilar molt suaument fins que trobem el Mas de l''Om. Des d’aquí el camí comença a enfilar seriosament fins al Pla de la Vaca. En el mig del Pla i a sobre de la cinglera i al mig d''uns boixos tenim l''entrada de dalt de la Cova del Pla de la Vaca, no és gens fàcil de trobar. La cova té un recorregut d’uns 15 o 20 metres, en pendent, i la sortida està al mig de la cinglera, se surt de la cova reculant a l’ entrada de dalt al Pla. Esmorzem mentre contemplem el Comanegra i el Puig de les Bruixes. 
Continuem pel mig del prat en direcció nord per trobar el camí que s''enfila en direcció al coll de Sant Marc. És un camí malmès per la natura, en no ser gaire transitat, però que no presenta cap dificultat, ni de pas ni d''orientació. Quan arribem al coll de Sant Marc, al mig d’un prat de falgueres, comencem a pujar per la forta però curta pujada pel mig d’una magnifica fageda fins el cim del Puig de Sant Marc (1.327 metres). 
Al Cim ens esperen unes vistes impressionants del Comanegra, puig de les Bruixes, i el sempre magnífic e inconfusible Bassegoda, al davant. 
Baixem tornant al Coll de Sant Marc per començar a pujar el Puig de les Bruixes. Sense cap pèrdua perquè es divisa tota l''estona, s''arriba al cim després d''una curta i costeruda pujada. 
 El Puig de les Bruixes amb els seus 1.393 metres d''altitud ofereix unes molt bones vistes d’un mar de muntanyes i el Comanegra al nostre davant. 
Des del Puig de les Bruixes es va resseguint el camí de la carena amb molt bones vistes i fent bones fotos, fins arribar a una fageda, on comença l''ascens definitiu i costerut que puja al Comanegra. Gairebé al cim hi ha una petita plana, on hi ha un rètol de l’Estat Francès. Continuem per arribar al cim del Comanegra que amb els seus 1.557 metres es considera el sostre de la comarca de la Garrotxa. 
Per baixar seguim les marques taronges i verdes, pel mig dels inclinats prats baixem molt directament fins a trobar el cotxe i donem per acabada aquesta magnifica i entretinguda ruta. Com diu el meu company de ruta és: “Una caminada imprescindible per a qualsevol excursionista”. 
Salut i bona caminada!!!', '{"en":"This moderate loop starts from Basses de Monars (1300m), accessible via a 7.7km dirt track from Rocabruna, suitable for most cars. The route begins with a descent, passing the ruins of a sheepfold and Mas Mitjà, before reaching Cal Bessó and the Romanesque church of Sant Sebastià (or Sant Feliu) de Monars.\n\nThe trail then climbs to Sant Marc (1327m), Puig de les Bruixes (1393m), and finally Comanegra (1557m), offering varied terrain and good views throughout. It''s a good option for hikers looking to explore the Monars area and its historical sites.","ca":"Aquesta ruta circular moderada comença des de les Basses de Monars (1300m), accessibles per una pista de terra de 7,7km des de Rocabruna, apta per a la majoria de cotxes. La ruta comença amb un descens, passant per les ruïnes d''un corral i el Mas Mitjà, abans d''arribar a Cal Bessó i l''església romànica de Sant Sebastià (o Sant Feliu) de Monars.\n\nEl sender puja després a Sant Marc (1327m), el Puig de les Bruixes (1393m) i finalment el Comanegra (1557m), oferint un terreny variat i bones vistes. És una bona opció per a excursionistes que vulguin explorar la zona de Monars i els seus llocs històrics.","es":"Esta ruta circular moderada comienza desde las Basses de Monars (1300m), accesibles por una pista de tierra de 7,7km desde Rocabruna, apta para la mayoría de coches. La ruta comienza con un descenso, pasando por las ruinas de un corral y el Mas Mitjà, antes de llegar a Cal Bessó y la iglesia románica de Sant Sebastià (o Sant Feliu) de Monars.\n\nEl sendero sube después a Sant Marc (1327m), el Puig de les Bruixes (1393m) y finalmente el Comanegra (1557m), ofreciendo un terreno variado y buenas vistas. Es una buena opción para excursionistas que quieran explorar la zona de Monars y sus lugares históricos."}'::jsonb, 'JEP BOIX', 11346, 757, 757, 1550, 893, 'moderate', 'loop', NULL, 16260, 1683, '2015-05-31', '2015-05', '[{"lat":42.329336,"lng":2.521044,"ele":1298.9},{"lat":42